def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]

    # Find the vertical blank separator between the framed panels and shapes.
    split = next(c for c in range(w) if all(grid[r][c] == 0 for r in range(h)))
    out = [row[:split] for row in grid]

    # Find connected colored shapes to the right of the separator. Their
    # coordinates, relative to the separator, correspond to panel coordinates.
    seen = set()
    shapes = []
    for r in range(h):
        for c in range(split, w):
            color = grid[r][c]
            if color == 0 or color == frame or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and split <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            shapes.append((color, frozenset((y, x - split) for y, x in cells)))

    # Match each panel's zero cells to the corresponding shape pattern.
    r = 0
    while r < h:
        if all(v == frame for v in out[r]):
            start = r + 1
            end = start
            while end < h and not all(v == frame for v in out[end]):
                end += 1
            holes = {(y - start, x) for y in range(start, end)
                     for x, value in enumerate(out[y]) if value == 0}
            for color, shape in shapes:
                if holes == shape:
                    for y in range(start, end):
                        for x in range(split):
                            if out[y][x] == 0:
                                out[y][x] = color
                    break
            r = end
        else:
            r += 1
    return out
